import type { IncomingMessage, ServerResponse } from "node:http";

type Handler = (request: IncomingMessage, response: ServerResponse) => Promise<void>;
type Failure = { code: string; status: number; message: string };

const failures: Record<string, Failure> = {
    invalid_json: { code: "invalid_json", status: 400, message: "The request body is not valid JSON." },
    not_found: { code: "not_found", status: 404, message: "The requested resource does not exist." },
};

export function fail(code: string): never {
    const failure = failures[code] ?? { code: "internal", status: 500, message: "The request failed." };
    throw Object.assign(new Error(failure.message), { code: failure.code, status: failure.status });
}

export function handle(handler: Handler) {
    return function wrapped(request: IncomingMessage, response: ServerResponse) {
        handler(request, response).catch(function onFailure(error: unknown) {
            const status = typeof error === "object" && error !== null && "status" in error ? Number(error.status) : 500;
            const code = typeof error === "object" && error !== null && "code" in error ? String(error.code) : "internal";
            response.writeHead(status, { "content-type": "application/json" });
            response.end(JSON.stringify({ error: code }));
        });
    };
}

export async function updateStatus(request: IncomingMessage): Promise<{ ok: true }> {
    const body = await new Promise<string>(function read(resolve, reject) {
        const chunks: Buffer[] = [];
        request.on("data", function onChunk(chunk: Buffer) {
            chunks.push(chunk);
        });
        request.on("end", function onEnd() {
            resolve(Buffer.concat(chunks).toString("utf8"));
        });
        request.on("error", reject);
    });
    try {
        JSON.parse(body);
    } catch {
        fail("invalid_json");
    }
    return { ok: true };
}
